SPELL_ABILITY.RESOLUTION_TIME_ACTION:
local answerDC = EffectDC():Make_Targets(0) local queryDC = EffectDC():Make_Chest(1) local player = EffectController() for i = 0, 4 do local card = player:Library_GetNth(i)
if card ~= nil then queryDC:Set_CardPtr(i, card)
if (card:GetCardType():Test(CARD_TYPE_CREATURE)) == false and (card:GetCardType():Test(CARD_TYPE_LAND)) == false then queryDC:QueryUnselect_CardPtr(i) end else break end end for j = 0, (MTG():GetNumberOfPlayers()-1) do local nthPlayer = MTG():GetNthPlayer(j) if nthPlayer ~= nil and nthPlayer ~= player then nthPlayer:RevealDCToMe(queryDC) end end player:ChooseItemFromDC( "CARD_QUERY_CHOOSE_A_CREATURE_OR_LAND_TO_PUT_INTO_YOUR_HAND", queryDC, answerDC, QUERY_FLAG_MAY)
